func ftNl(b []byte, i int32) int32 {
	var k int32 = i
	for (k < port.BlobLen(b)) && (port.BlobU8(b, k) != 10) {
		k += 1
	}
	return k
}

func ftTab(b []byte, i int32, lim int32) int32 {
	var k int32 = i
	for (k < lim) && (port.BlobU8(b, k) != 9) {
		k += 1
	}
	return k
}

func ftHexval(c int32) int32 {
	if (c >= 48) && (c <= 57) {
		return c - 48
	}
	if (c >= 97) && (c <= 102) {
		return c - 87
	}
	return -1
}

func ftHexInto(b []byte, from int32, to int32, c *port.Cells) int32 {
	// Decode the hex pairs in b[from, to) into c (cleared first); `-` is
	// the empty string.
	var k int32 = from
	port.CellsDrop(c, 0)
	if ((to - from) == 1) && (port.BlobU8(b, from) == 45) {
		return 0
	}
	for (k + 1) < (to + 0) {
		port.CellsPush(c, (ftHexval(port.BlobU8(b, k))*16)+ftHexval(port.BlobU8(b, k+1)))
		k += 2
	}
	return port.CellsLen(c)
}

func ftCompare(out *port.Cells, b []byte, from int32, to int32) int32 {
	// -1 when `out` is exactly the hex in b[from, to) (`-` is empty); -2
	// for a length difference; else the index of the first differing byte.
	var n int32 = (to - from) / 2
	var i int32 = 0
	if ((to - from) == 1) && (port.BlobU8(b, from) == 45) {
		n = 0
	}
	if port.CellsLen(out) != n {
		return -2
	}
	for i < n {
		if port.CellsAt(out, i) != ((ftHexval(port.BlobU8(b, from+(i*2))) * 16) + ftHexval(port.BlobU8(b, from+((i*2)+1)))) {
			return i
		}
		i += 1
	}
	return -1
}

func ftDec(b []byte, from int32, to int32) int32 {
	var k int32 = from
	var v int32 = 0
	for k < to {
		v = (v * 10) + (port.BlobU8(b, k) - 48)
		k += 1
	}
	return v
}

func ftFilter(b []byte, from int32, to int32) int32 {
	// The `pf-filter` code for a filter name, told apart by length.
	var n int32 = to - from
	if n == 14 {
		return pdffilter.PfFHex()
	}
	if n == 13 {
		return pdffilter.PfFA85()
	}
	if n == 9 {
		return pdffilter.PfFLzw()
	}
	if n == 11 {
		return pdffilter.PfFFlate()
	}
	if n == 15 {
		return 5
	}
	return 0
}

func ftParm(b []byte, from int32, to int32, key int32, dflt int32) int32 {
	// The value of `key` in `P=1,C=2` parameters (`-` for none): the key is
	// named by its first letter and, for C, its fourth (Columns / Colors).
	// Keys: 80 Predictor, 67 Columns, 99 Colors, 66 BitsPerComponent,
	// 69 EarlyChange.
	var k int32 = from
	var e int32 = 0
	var eq int32 = 0
	var id int32 = 0
	for k < to {
		e = k
		for (e < to) && (port.BlobU8(b, e) != 44) {
			e += 1
		}
		eq = k
		for (eq < e) && (port.BlobU8(b, eq) != 61) {
			eq += 1
		}
		if eq < e {
			id = port.BlobU8(b, k)
			if id == 67 {
				if port.BlobU8(b, k+3) == 111 {
					id = 99
				}
			}
			if id == key {
				return ftDec(b, eq+1, e)
			}
		}
		k = e + 1
	}
	return dflt
}

func ftRun(f []byte, s1 int32, s2 int32, s3 int32, s4 int32, inp *port.Cells, out *port.Cells, tmp *port.Cells, st *port.Cells) int32 {
	// Run the row whose filter is f[s1+1, s2), parameters f[s2+1, s3) and
	// input hex f[s3+1, s4): the filter, then a predictor when /Predictor
	// says so. Answers the first non-zero status, with out filled.
	var code int32 = ftFilter(f, s1+1, s2)
	var pred int32 = ftParm(f, s2+1, s3, 80, 1)
	var early int32 = ftParm(f, s2+1, s3, 69, 1)
	var status int32 = 0
	var n int32 = 0
	var p int32 = 0
	n = ftHexInto(f, s3+1, s4, inp)
	port.CellsDrop(out, 0)
	port.CellsDrop(tmp, 0)
	if pred > 1 {
		status = pdffilter.PfRun(code, port.CellsBlob(inp), 0, n, tmp, st, early)
		p = pdffilter.PfPredict(tmp, 0, port.CellsLen(tmp), out, pred, ftParm(f, s2+1, s3, 99, 1), ftParm(f, s2+1, s3, 66, 8), ftParm(f, s2+1, s3, 67, 1))
		if status == 0 {
			status = p
		}
	} else {
		status = pdffilter.PfRun(code, port.CellsBlob(inp), 0, n, out, st, early)
	}
	return status
}

func TestEveryRowOfTheFilterCorpus(emonT *testing.T) {
	var f []byte = port.TestFile("pdf/filters.txt")
	var inp *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var e int32 = 0
	var s1 int32 = 0
	var s2 int32 = 0
	var s3 int32 = 0
	var s4 int32 = 0
	var s5 int32 = 0
	var status int32 = 0
	for pos < n {
		line += 1
		e = ftNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			rows += 1
			s1 = ftTab(f, pos, e)
			s2 = ftTab(f, s1+1, e)
			s3 = ftTab(f, s2+1, e)
			s4 = ftTab(f, s3+1, e)
			s5 = ftTab(f, s4+1, e)
			status = ftRun(f, s1, s2, s3, s4, inp, out, tmp, st)
			var t *strings.Builder = port.NewText()
			pdffilter.PfStatusEmitName(t, status)
			port.AssertTextSpan(emonT, t, f, s4+1, s5, "status", line)
			port.AssertEqAt(emonT, ftCompare(out, f, s5+1, e), -1, "output", line)
		}
		pos = e + 1
	}
	port.AssertThat(emonT, rows > 60, "the corpus was read")
}

func TestFiltersAppendToWhatIsThere(emonT *testing.T) {
	var out *port.Cells = port.NewCells()
	port.CellsPush(out, 33)
	port.AssertEq(emonT, pdffilter.PfHex(port.TextBlob("4849>"), 0, 5, out), 0, "status")
	port.AssertCellsHex(emonT, out, "214849", "appended after the existing byte")
}

func TestTheInputRangeIsRespected(emonT *testing.T) {
	var out *port.Cells = port.NewCells()
	port.AssertEq(emonT, pdffilter.PfA85(port.TextBlob("xx87cURDZ~>xx"), 2, 11, out), 0, "a85 status")
	port.AssertCellsHex(emonT, out, "48656c6c6f", "a85 range")
}

func TestCryptIsTheIdentityAndImageFiltersAreDeclined(emonT *testing.T) {
	var out *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	port.AssertEq(emonT, pdffilter.PfRun(pdffilter.PfFCrypt(), port.HexBlob("0102"), 0, 2, out, st, 1), 0, "crypt")
	port.AssertCellsHex(emonT, out, "0102", "unchanged")
	port.AssertEq(emonT, pdffilter.PfRun(pdffilter.PfFDct(), port.HexBlob("ffd8"), 0, 2, out, st, 1), pdffilter.PfImageFilter(), "dct declined")
	port.AssertEq(emonT, port.CellsLen(out), 2, "out untouched by an image filter")
	port.AssertEq(emonT, pdffilter.PfRun(99, port.HexBlob("00"), 0, 1, out, st, 1), pdffilter.PfUnsupported(), "unknown")
}
